import 'package:flutter/material.dart';
import 'package:intl/intl.dart';
import '../../core/data/transaction_repository.dart';
class TransactionsPage extends StatefulWidget{const TransactionsPage({super.key,this.businessId});final String? businessId;@override State<TransactionsPage> createState()=>_TransactionsPageState();}
class _TransactionsPageState extends State<TransactionsPage>{final _repo=TransactionRepository();late Future<List<TransactionSummary>> _future;String _query='';@override void initState(){super.initState();_future=_load();}Future<List<TransactionSummary>> _load()=>widget.businessId==null?Future.value(const[]):_repo.loadTransactions(widget.businessId!);Future<void> _refresh()async{setState(()=>_future=_load());await _future;}@override Widget build(BuildContext context){final c=NumberFormat.currency(locale:'id_ID',symbol:'Rp ',decimalDigits:0);return Column(children:[Padding(padding:const EdgeInsets.all(16),child:TextField(decoration:const InputDecoration(prefixIcon:Icon(Icons.search),hintText:'Cari nomor transaksi'),onChanged:(v)=>setState(()=>_query=v))),Expanded(child:RefreshIndicator(onRefresh:_refresh,child:FutureBuilder<List<TransactionSummary>>(future:_future,builder:(context,s){if(s.connectionState!=ConnectionState.done)return const Center(child:CircularProgressIndicator());if(s.hasError)return ListView(children:[const SizedBox(height:120),Center(child:Text('Gagal memuat transaksi: ${s.error}'))]);final data=(s.data??const<TransactionSummary>[]).where((t)=>t.transactionNo.toLowerCase().contains(_query.toLowerCase())).toList();if(data.isEmpty)return ListView(children:const[SizedBox(height:120),Center(child:Text('Belum ada transaksi'))]);return ListView.builder(padding:const EdgeInsets.fromLTRB(16,0,16,16),itemCount:data.length,itemBuilder:(context,i){final t=data[i];return Card(child:ListTile(leading:const CircleAvatar(child:Icon(Icons.receipt_long)),title:Text(t.transactionNo),subtitle:Text('${t.paymentMethod} • ${DateFormat('dd MMM HH:mm','id_ID').format(t.transactionAt.toLocal())}'),trailing:Text(c.format(t.total))));});})))]);}}
